SELECT id, account_number, password, balance, member_id, created_at, updated_at
FROM account
WHERE member_id = #{memberId}

SELECT id, account_number, password, balance, member_id, created_at, updated_at
FROM account
WHERE id = #{id}

SELECT id, account_number, password, balance, member_id, created_at, updated_at
FROM account
WHERE account_number = #{accountNumber}

SELECT count(*)
FROM account
WHERE account_number = #{accountNumber}
